package com.muthumol.player.dummy;
import android.content.*;import android.content.pm.PackageManager;import android.media.tv.TvContract;import android.net.Uri;import android.os.Build;import java.util.*;import java.util.concurrent.*;
final class TvLauncher {
 static final ExecutorService worker=Executors.newSingleThreadExecutor();static long last;static void publish(Context c,List<Movie> movies){if(Build.VERSION.SDK_INT<26||!c.getPackageManager().hasSystemFeature(PackageManager.FEATURE_LEANBACK)||System.currentTimeMillis()-last<30000)return;last=System.currentTimeMillis();List<Movie> snapshot=new ArrayList<>(movies);worker.execute(()->{try{android.content.SharedPreferences p=c.getSharedPreferences("tv-launcher",0);long channel=p.getLong("channel",0);if(!c.getSharedPreferences("alerts",0).getBoolean("launcher",true)){if(channel>0)c.getContentResolver().delete(Uri.parse("content://android.media.tv/channel/"+channel),null,null);p.edit().remove("channel").apply();return;}ContentResolver r=c.getContentResolver();if(channel==0){ContentValues v=new ContentValues();v.put("display_name","TG stream");v.put("type","TYPE_PREVIEW");v.put("app_link_intent_uri",new Intent(c,MainActivity.class).toUri(Intent.URI_INTENT_SCHEME));Uri row=r.insert(TvContract.Channels.CONTENT_URI,v);if(row==null)return;channel=ContentUris.parseId(row);p.edit().putLong("channel",channel).apply();}r.delete(Uri.parse("content://android.media.tv/preview_program"),"channel_id=?",new String[]{""+channel});int count=0;for(Movie m:TvLibrary.homeEntries(snapshot)){if(!LibraryContent.visible(c,m))continue;if(count++>=12)break;ContentValues v=new ContentValues();v.put("channel_id",channel);v.put("type",MediaTitle.parse(m.title).episodic()?1:0);v.put("title",MediaTitle.parse(m.title).display());v.put("description",m.savedPosition(c)>0?"Continue · "+CinemaInfo.time(m.savedPosition(c)):"Watch on TG stream");v.put("poster_art_uri","android.resource://"+c.getPackageName()+"/drawable/app_banner");v.put("intent_uri",new Intent(c,MainActivity.class).putExtra("launcherMovie",m.json().toString()).toUri(Intent.URI_INTENT_SCHEME));v.put("internal_provider_id",VideoCopies.key(m));r.insert(Uri.parse("content://android.media.tv/preview_program"),v);}}catch(Exception e){BetaLog.event("tv_launcher",e.getClass().getSimpleName());}});}
}
